// Generated by vibes-espmatter – OpenTelemetry metrics of the Matter controller's paired devices.
#include "espm_matter.h"
#include "espm_otel.h"

#include <cstdio>
#include <cstring>
#include <initializer_list>

/** Attributes of a node's metrics: node id, endpoint and name (`;` and `=` replaced). */
static void attrs_of(const mesp_node_values &node, uint16_t ep, char *out, size_t len)
{
    char name[MESP_NODE_NAME_LEN];
    strlcpy(name, node.name, sizeof(name));
    for (char *c = name; *c; c++)
        if (*c == ';' || *c == '=') *c = '_';
    snprintf(out, len, "node=0x%llx;ep=%u%s%s", (unsigned long long)node.node_id, ep, name[0] ? ";name=" : "", name);
}

/** The node's last known values as metrics; battery, power and energy are the node's (ep 0). */
static void record(const mesp_node_values &node)
{
    char attrs[80];
    const mesp_battery_t &bat = *node.battery;
    attrs_of(node, 0, attrs, sizeof(attrs));
    if (bat.updated && bat.percent_x2 >= 0) mesp_otel_gauge("matter.battery", "%", bat.percent_x2 / 2.0, attrs);
    else if (bat.updated) mesp_otel_remove("matter.battery", attrs);
    // 0 ok, 1 warning, 2 critical – also from devices that don't report a percentage.
    if (bat.updated && bat.level >= 0) mesp_otel_gauge("matter.battery.level", "1", bat.level, attrs);
    else if (bat.updated) mesp_otel_remove("matter.battery.level", attrs);
    if (node.power->updated) mesp_otel_gauge("matter.power", "W", node.power->mw / 1000.0, attrs);
    if (node.power->energy_updated)
        mesp_otel_counter("matter.energy.imported", "kWh", node.power->energy_mwh / 1e6, attrs);
    for (uint8_t i = 0; i < node.ep_count; i++) {
        const mesp_measure_t &m = node.measure[i];
        const mesp_endpoint_state_t &state = node.state[i];
        attrs_of(node, node.ep[i], attrs, sizeof(attrs));
        if (m.temp_at) mesp_otel_gauge("matter.temperature", "Cel", m.temp / 100.0, attrs);
        if (m.humidity_at) mesp_otel_gauge("matter.humidity", "%", m.humidity / 100.0, attrs);
        if (state.on >= 0) mesp_otel_gauge("matter.onoff", "1", state.on, attrs);
        if (state.level >= 0) mesp_otel_gauge("matter.brightness", "%", state.level * 100.0 / 254, attrs);
        if (state.ct > 0) mesp_otel_gauge("matter.color_temperature", "K", 1e6 / state.ct, attrs);
    }
}

/** Stop sending the node's metrics (offline, removed, or renamed: its attributes change). */
static void forget(const mesp_node_values &node)
{
    char attrs[80];
    attrs_of(node, 0, attrs, sizeof(attrs));
    for (const char *name : {"matter.battery", "matter.battery.level", "matter.power", "matter.energy.imported"})
        mesp_otel_remove(name, attrs);
    for (uint8_t i = 0; i < node.ep_count; i++) {
        attrs_of(node, node.ep[i], attrs, sizeof(attrs));
        for (const char *name : {"matter.temperature", "matter.humidity", "matter.onoff", "matter.brightness",
                                 "matter.color_temperature"})
            mesp_otel_remove(name, attrs);
    }
}

void mesp_otel_metrics_init()
{
    mesp_matter_on_values([](const mesp_node_values &node, bool current) { current ? record(node) : forget(node); });
}
